(()=>{'use strict';const c=window.TEMPLATE_CONFIG,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),params=new URLSearchParams(location.search),type=c.type;
document.body.style.setProperty('--accent',c.accent);document.body.style.setProperty('--bg',c.bg);document.body.style.setProperty('--ink',c.ink);document.body.style.setProperty('--panel',c.panel);document.body.style.setProperty('--muted',c.muted);document.body.className=c.layout+' '+(c.light?'light':'dark');document.title=c.name+' · '+({home:'Start',collection:c.collectionLabel,journal:'Journal',article:'Story',contact:'Kontakt',about:'Über uns',info:'Hinweise',cart:'Merkliste'}[document.body.dataset.page]||'Website');
const audio=type==='radio'||type==='music'||type==='dj',shop=type==='shop',pages=[['index.html','Home'],['kollektion.html',c.collectionLabel],['journal.html','Journal'],['ueber.html','Über uns'],['kontakt.html',type==='dj'?'Booking':'Kontakt']];
$('#header').innerHTML=`<div class="wrap header-row"><a class="brand" href="index.html" aria-label="${esc(c.name)} Startseite"><img src="assets/logo.svg" alt="${esc(c.name)}"><span>${esc(c.name)}<small>${esc(c.subtitle)}</small></span></a><nav aria-label="Hauptnavigation" id="navigation">${pages.map(([url,label])=>`<a href="${url}" ${location.pathname.endsWith(url)?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav><div class="header-actions"><button class="icon-button" id="search-open" aria-label="Suche öffnen">⌕</button>${shop?'<a class="button small" href="merkliste.html">Merkliste <span id="cart-count">0</span></a>':`<a class="button small" href="${audio?'index.html#audio':'kontakt.html'}">${audio?'Demo anhören':'Projekt anfragen'} ↗</a>`}<button class="icon-button menu" id="menu" aria-label="Menü öffnen" aria-controls="navigation" aria-expanded="false">☰</button></div></div>`;
$('#footer').innerHTML=`<div class="wrap footer-row"><a class="brand" href="index.html"><img src="assets/logo.svg" alt=""><span>${esc(c.name)}<small>${esc(c.subtitle)}</small></span></a><p>${esc(c.footer)}</p><div><a href="hinweise.html">Demo & Hinweise</a><br><small>Fiktives Gestaltungsbeispiel · © 2026</small></div></div>`;
if(c.publicDemo){const b=document.createElement('aside');b.className='demo-banner';b.innerHTML=`<span>${esc(c.name)} · LIVE-DEMO</span><a href="/#product/${encodeURIComponent(c.id)}">Template ansehen ↗</a><a href="/anpassung.html?produkt=${encodeURIComponent(c.id)}">Anpassung anfragen ↗</a>`;$('#header').after(b);document.addEventListener('contextmenu',e=>{if(e.target instanceof Element&&(e.target.closest('img,.hero-art')||getComputedStyle(e.target).backgroundImage!=='none'))e.preventDefault();});document.addEventListener('dragstart',e=>{if(e.target instanceof Element&&e.target.closest('img'))e.preventDefault();});}
const intro=(k,title,text)=>`<section class="wrap intro"><span class="eyebrow">${esc(k)}</span><h1>${esc(title)}</h1><p>${esc(text)}</p></section>`;
const title=(text,link,label='Alle entdecken')=>`<div class="section-title"><h2>${esc(text)}</h2>${link?`<a href="${link}">${esc(label)} →</a>`:''}</div>`;
const money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n/100);
const card=(item,i=0)=>`<article class="item-card" data-category="${esc(item.category)}" data-search="${esc(item.title+' '+item.text+' '+item.category)}"><button class="card-image crop-${i%4}" data-detail="${esc(item.id)}" aria-label="${esc(item.title)} ansehen"><img src="${esc(item.image||'assets/hero.webp')}" alt="${esc(item.imageAlt||c.imageAlt)}" loading="lazy"><span class="card-number">${String(i+1).padStart(2,'0')}</span></button><div class="card-copy"><span class="eyebrow">${esc(item.category)}${item.time?' / '+esc(item.time):''}</span><h3><button class="text-button" data-detail="${esc(item.id)}">${esc(item.title)}</button></h3><p>${esc(item.text)}</p>${shop?`<div class="card-bottom"><strong>${money(item.price)}</strong><button class="button small" data-add="${esc(item.id)}">Merken ＋</button></div>`:`<button class="read-link" data-detail="${esc(item.id)}">${esc(c.detailLabel||'Mehr erfahren')} ↗</button>`}</div></article>`;
const story=(n,i)=>`<a class="story-card" href="artikel.html?id=${encodeURIComponent(n.id)}"><div class="story-image crop-${i%4}"><img src="assets/hero.webp" alt="${esc(c.imageAlt)}" loading="lazy"></div><span class="eyebrow">${esc(n.category)} · ${esc(n.date)}</span><h3>${esc(n.title)}</h3><p>${esc(n.teaser)}</p><span class="read-link">Story lesen ↗</span></a>`;
const player=()=>`<section class="wrap audio-player" id="audio" aria-label="Audioplayer"><div class="audio-cover"><img src="assets/hero.webp" alt=""></div><div class="audio-title"><span class="eyebrow">${c.streamUrl?'STREAM':'LOKALE AUDIO-DEMO'}</span><h2>${esc(c.audioTitle||'Studio Signal')}</h2><small>${c.streamUrl?'Stream gemäß Konfiguration':'Eigener synthetischer Demo-Loop · kein Live-Sender'}</small></div><button class="play-button" id="play" aria-label="Demo-Audio abspielen">▶</button><div class="wave" aria-hidden="true">${Array.from({length:48},(_,i)=>'<i style="--height:'+ (12+(i*37%67))+'%"></i>').join('')}</div><label class="volume">Lautstärke<input id="volume" type="range" min="0" max="1" step="0.05" value="0.3"></label><p id="audio-status" role="status">Bereit</p><audio id="audio-element" preload="none" src="${esc(c.streamUrl||'assets/demo-audio.wav')}" loop></audio></section>`;
const home=()=>`<section class="hero"><div class="hero-art" role="img" aria-label="${esc(c.imageAlt)}"></div><div class="wrap hero-content"><span class="eyebrow">${esc(c.kicker)}</span><h1>${esc(c.headline)}<em>${esc(c.emphasis)}</em></h1><p>${esc(c.description)}</p><div class="button-row"><a class="button" href="${audio?'#audio':'kollektion.html'}">${esc(c.cta)} ↗</a><a class="button outline" href="kollektion.html">${esc(c.collectionLabel)} →</a></div><span class="hero-caption">${esc(c.heroCaption||c.subtitle)}</span></div></section>${audio?player():''}<section class="wrap section"><div class="home-collection">${title(c.sectionTitle,'kollektion.html')}<div class="card-grid">${c.items.slice(0,4).map(card).join('')}</div></div></section>${c.type==='radio'?`<section class="wrap timeline"><span class="eyebrow">DEMO-PROGRAMM</span>${c.items.map(x=>`<button data-detail="${esc(x.id)}"><strong>${esc(x.time)}</strong><span>${esc(x.title)}</span></button>`).join('')}</section>`:''}<section class="wrap section">${title(c.journalTitle||'STORIES & PERSPEKTIVEN','journal.html')}<div class="stories-grid">${c.stories.slice(0,3).map(story).join('')}</div></section><section class="wrap bottom-cta"><div><span class="eyebrow">${esc(c.ctaKicker||'LET’S CONNECT')}</span><h2>${esc(c.bottomTitle)}</h2><p>${esc(c.bottomText)}</p></div><a class="button" href="kontakt.html">${type==='dj'?'Booking anfragen':'Kontakt aufnehmen'} ↗</a></section>`;
function collection(){const cats=['Alle',...new Set(c.items.map(x=>x.category))];return intro(c.subtitle,c.collectionTitle,c.collectionText)+`<section class="wrap section"><div class="toolbar"><div class="filters">${cats.map((x,i)=>`<button data-filter="${esc(x)}" class="${!i?'active':''}" aria-pressed="${!i}">${esc(x)}</button>`).join('')}</div><label class="search-field"><span class="sr-only">${esc(c.collectionLabel)} durchsuchen</span><input type="search" id="collection-search" placeholder="Durchsuchen …"></label></div><p id="filter-count" role="status">${c.items.length} Einträge</p><div class="card-grid">${c.items.map(card).join('')}</div><p id="empty" hidden>Keine passenden Einträge. Ändere die Kategorie oder den Suchbegriff.</p></section>`;}
function journal(){return intro('JOURNAL',c.journalTitle||'STORIES & PERSPEKTIVEN','Gedanken, Hintergründe und Geschichten aus unserer Welt.')+`<section class="wrap section"><label class="search-field"><span class="sr-only">Journal durchsuchen</span><input id="journal-search" type="search" placeholder="Geschichten durchsuchen …"></label><p id="journal-count" role="status">${c.stories.length} Geschichten</p><div class="stories-grid">${c.stories.map(story).join('')}</div><p id="journal-empty" hidden>Keine passende Geschichte gefunden.</p></section>`;}
function article(){const n=c.stories.find(x=>x.id===params.get('id'));if(!n)return intro('JOURNAL','Geschichte auswählen','Entdecke unsere aktuellen Beiträge.')+`<section class="wrap section"><div class="stories-grid">${c.stories.map(story).join('')}</div></section>`;return intro(n.category,n.title,n.teaser)+`<article class="wrap prose section"><img class="article-image" src="assets/hero.webp" alt="${esc(c.imageAlt)}"><p class="eyebrow">${esc(n.date)} · ${esc(c.name)} Journal · Demo</p>${n.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('')}<blockquote>${esc(n.quote||c.footer)}</blockquote><a class="button outline" href="journal.html">← Zum Journal</a></article>`;}
function contact(){return intro(type==='dj'?'BOOKING & COLLABORATION':'LET’S TALK',c.contactTitle||'DEIN NÄCHSTER SCHRITT.','Erstelle eine Anfrage für dein Vorhaben.')+`<section class="wrap section contact-layout"><aside><h2>${esc(c.contactAside||'Gute Ideen beginnen mit einem Gespräch.')}</h2><p>${esc(c.contactText||'Erzähl uns von deinem Projekt und den Vorstellungen, die dich antreiben.')}</p><div class="note"><strong>Lokaler Anfrageentwurf</strong><p>Dieses Formular erstellt einen Entwurf auf deinem Gerät. Es versendet und speichert keine Anfrage auf einem Server.${c.email?' Du kannst den Entwurf anschließend in deinem E-Mail-Programm öffnen.':''}</p></div></aside><form id="contact-form" class="panel"><label>Name *<input name="name" autocomplete="name" required maxlength="100"></label><label>E-Mail *<input name="email" type="email" autocomplete="email" required maxlength="180"></label><label>Anliegen *<select name="subject" required><option value="">Bitte wählen</option>${(shop?['Produktfrage','Angebot anfragen','Sonstiges']:type==='dj'?['Booking','Zusammenarbeit','Presse','Sonstiges']:['Projektanfrage','Zusammenarbeit','Feedback','Sonstiges']).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Nachricht *<textarea name="message" required minlength="10" maxlength="5000" rows="6"></textarea></label><label class="checkbox"><input type="checkbox" required><span>Ich verstehe, dass ein lokaler Entwurf erstellt und noch nichts versendet wird. *</span></label><button class="button" type="submit">Entwurf erstellen →</button><p id="form-status" role="status"></p><div id="draft-result" hidden><h3>Dein Entwurf ist bereit.</h3><textarea id="draft" readonly rows="8" aria-label="Anfrageentwurf"></textarea><div class="button-row"><button type="button" class="button small" id="draft-download">Herunterladen ↓</button><button type="button" class="button outline small" id="draft-copy">Kopieren</button>${c.email?'<button type="button" class="button outline small" id="draft-email">E-Mail-Programm öffnen</button>':''}</div></div></form></section>`;}
function about(){return intro('ABOUT '+c.name,c.aboutTitle,c.aboutIntro)+`<article class="wrap section about-layout"><img src="assets/hero.webp" alt="${esc(c.imageAlt)}"><div>${c.aboutParagraphs.map(p=>'<p>'+esc(p)+'</p>').join('')}<a class="button" href="kontakt.html">Kontakt aufnehmen ↗</a></div></article>`;}
function info(){return intro('TEMPLATE / HINWEISE','DIE IDEE HINTER DER DEMO.','Funktionsumfang und Hinweise zu dieser Website.')+`<article class="wrap prose section"><h2>Illustrative Inhalte</h2><p>${esc(c.name)} ist eine fiktive Marke für dieses NeonMind Website-Template. Personen, Programme, Produkte, Projekte, Preise und Termine sind Beispieldaten. Die Bildmotive sind KI-gestützt erstellt und zeigen keine bestätigten realen Personen oder Angebote.</p><h2>Enthaltene Funktionen</h2><p>Responsive Seiten, mobile Navigation, Suche, Kategorienfilter, Detailansichten, Journal und lokaler Kontaktentwurf.${audio?' Ein lokaler synthetischer Demo-Loop ist abspielbar. Eine eigene Stream-URL kann in der Konfiguration hinterlegt werden; Streamingserver, Musikrechte und Sendebetrieb sind nicht enthalten.':''}${shop?' Die Merkliste speichert gewählte Demo-Produkte lokal im Browser und erstellt eine Anfrageliste. Es gibt keine Bestellung, Bezahlung, Lagerverwaltung oder verbindliche Preisberechnung.':''}</p><h2>Vor der eigenen Veröffentlichung</h2><p>Beispieldaten ersetzen, Kontaktwege einrichten, eigene Betreiber- und Datenschutzangaben ergänzen. Keine erfundenen Betreiberangaben enthalten. Eine individuelle CMS-Integration und serverseitiger Formularversand sind separat zu vereinbaren.</p><h2>Bearbeitbare Dateien</h2><p>HTML, CSS und JavaScript sowie eine zentrale Konfiguration für Namen, Farben, Texte, Inhalte und Bildbeschreibungen. Logo als bearbeitbares SVG, lokale Schriften mit Lizenz. Rastermotive als Bilddateien; keine erfundenen PSD-Ebenen.</p><a class="button" href="index.html">Zur Startseite →</a></article>`;}
let cart=[];try{cart=JSON.parse(localStorage.getItem('nm-template-'+c.id)||'[]');if(!Array.isArray(cart))cart=[];}catch{}cart=cart.filter(id=>c.items.some(x=>x.id===id));const saveCart=()=>{try{localStorage.setItem('nm-template-'+c.id,JSON.stringify(cart));}catch{}if($('#cart-count'))$('#cart-count').textContent=cart.length;};saveCart();
function cartPage(){return intro('UNVERBINDLICHE AUSWAHL','DEINE MERKLISTE.','Demo-Produkte sammeln und eine lokale Anfrage vorbereiten. Keine Bestellung, keine Zahlung.')+`<section class="wrap prose section">${cart.length?cart.map(id=>{const x=c.items.find(x=>x.id===id);return `<div class="cart-row"><div><h2>${esc(x.title)}</h2><p>Beispielpreis: ${money(x.price)}</p></div><button class="button outline small" data-remove="${esc(id)}">Entfernen</button></div>`;}).join('')+`<p class="cart-total">Unverbindliche Beispielsumme: ${money(cart.reduce((n,id)=>n+c.items.find(x=>x.id===id).price,0))}</p><a class="button" href="kontakt.html?auswahl=${encodeURIComponent(cart.join(','))}">Anfrageliste vorbereiten →</a>`:'<p>Deine Merkliste ist leer.</p><a class="button" href="kollektion.html">Produkte entdecken →</a>'}</section>`;}
const renders={home,collection,journal,article,contact,about,info,cart:cartPage};$('#main').innerHTML=(renders[document.body.dataset.page]||home)();
if(c.layout==='radio-editorial'&&document.body.dataset.page==='home'){const hero=$('.hero'),player=$('.audio-player');if(hero&&player)hero.append(player);const sections=[...document.querySelectorAll('#main>.section')];if(sections.length>=2){const duo=document.createElement('div');duo.className='wrap editorial-duo';sections[0].before(duo);for(const section of [sections[1],sections[0]]){section.classList.remove('wrap');duo.append(section);}}}
if(c.ranking&&document.body.dataset.page==='home'){const box=document.createElement('section');box.className='wrap game-meta section';box.innerHTML='<div><h2>'+esc(c.rankingLabel||'TOP GUILDS / DEMO')+'</h2><ol class="ranking">'+c.ranking.map((r,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(r[0])+'</strong><small>'+new Intl.NumberFormat('de-DE').format(r[1])+'</small></li>').join('')+'</ol></div><aside class="panel"><span class="eyebrow">UPCOMING / FIKTIVES EVENT</span><h2>'+esc(c.event.title)+'</h2><p>'+esc(c.event.description)+'</p><p><strong>'+esc(c.event.date)+'</strong></p><a class="button outline" href="kontakt.html">Interesse als Entwurf ↗</a></aside>';document.querySelector('#main>.section')?.after(box);}
if(c.bracket&&document.body.dataset.page==='home'){const panel=document.createElement('section');panel.className='wrap section bracket-section';panel.innerHTML='<div class="section-title"><h2>WORLD CHAMPIONSHIP / DEMO</h2><span class="eyebrow">FIKTIVER TURNIERBAUM</span></div><div class="bracket"><div><h3>Quarter Finals</h3>'+c.bracket.map(m=>'<div class="match"><p><strong>'+esc(m[0])+'</strong><span>'+m[2]+'</span></p><p><strong>'+esc(m[1])+'</strong><span>'+m[3]+'</span></p></div>').join('')+'</div><div><h3>Semi Finals</h3><div class="match"><p><strong>Nova</strong><span>2</span></p><p><strong>Zenith</strong><span>0</span></p></div><div class="match"><p><strong>Falcon</strong><span>1</span></p><p><strong>Titan</strong><span>2</span></p></div></div><div><h3>Grand Final</h3><div class="match"><p><strong>Nova</strong><span>–</span></p><p><strong>Titan</strong><span>–</span></p></div></div></div>';document.querySelector('#main>.hero')?.after(panel);}
const modal=$('#detail-dialog');function detail(id){const x=c.items.find(x=>x.id===id);if(!x)return;$('#detail-content').innerHTML=`<img class="detail-image" src="${esc(x.image||'assets/hero.webp')}" alt="${esc(x.imageAlt||c.imageAlt)}"><span class="eyebrow">${esc(x.category)}</span><h2 id="detail-title">${esc(x.title)}</h2><p>${esc(x.text)}</p>${(x.details||[]).map(t=>'<p>'+esc(t)+'</p>').join('')}${x.time?'<p><strong>Demo-Zeit:</strong> '+esc(x.time)+'</p>':''}${shop?'<p>Beispielpreis: '+money(x.price)+'</p><button class="button" data-add="'+esc(x.id)+'">Zur Merkliste ＋</button>':'<a class="button" href="kontakt.html">Anfrage vorbereiten ↗</a>'}<p class="muted">Illustrative Demo-Inhalte.</p>`;modal.showModal();}
document.addEventListener('click',e=>{const d=e.target.closest('[data-detail]');if(d)detail(d.dataset.detail);const add=e.target.closest('[data-add]');if(add){if(!cart.includes(add.dataset.add))cart.push(add.dataset.add);saveCart();$('#toast').textContent='Zur Merkliste hinzugefügt.';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2000);}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x!==remove.dataset.remove);saveCart();$('#main').innerHTML=cartPage();}});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#menu').onclick=()=>{const on=$('#menu').getAttribute('aria-expanded')!=='true';$('#menu').setAttribute('aria-expanded',on);$('#navigation').classList.toggle('open',on);};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');document.querySelectorAll('dialog[open]').forEach(d=>d.close());}},true);
const search=$('#search-dialog');$('#search-open').onclick=()=>{search.showModal();$('#global-search').value='';searchResults('');$('#global-search').focus();};function searchResults(q){q=q.toLocaleLowerCase('de');const items=[...c.items.map(x=>({title:x.title,type:x.category,url:'kollektion.html?detail='+encodeURIComponent(x.id)})),...c.stories.map(x=>({title:x.title,type:'Journal',url:'artikel.html?id='+encodeURIComponent(x.id)}))].filter(x=>(x.title+' '+x.type).toLocaleLowerCase('de').includes(q));$('#global-results').innerHTML=items.length?items.map(x=>`<a href="${x.url}"><small>${esc(x.type)}</small><strong>${esc(x.title)}</strong><span>↗</span></a>`).join(''):'<p>Keine Treffer gefunden.</p>';}
$('#global-search').oninput=e=>searchResults(e.target.value.trim());if(params.has('detail'))detail(params.get('detail'));
let filter='Alle';function applyFilter(){const q=($('#collection-search')?.value||'').trim().toLocaleLowerCase('de');let count=0;document.querySelectorAll('.item-card').forEach(el=>{el.hidden=(filter!=='Alle'&&el.dataset.category!==filter)||!el.dataset.search.toLocaleLowerCase('de').includes(q);if(!el.hidden)count++;});if($('#filter-count'))$('#filter-count').textContent=count+' Einträge';if($('#empty'))$('#empty').hidden=!!count;}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});applyFilter();});if($('#collection-search'))$('#collection-search').oninput=applyFilter;
if($('#journal-search'))$('#journal-search').oninput=e=>{let count=0;document.querySelectorAll('.story-card').forEach(el=>{el.hidden=!el.textContent.toLocaleLowerCase('de').includes(e.target.value.trim().toLocaleLowerCase('de'));if(!el.hidden)count++;});$('#journal-empty').hidden=!!count;$('#journal-count').textContent=count+' Geschichten';};
if($('#audio-element')){const el=$('#audio-element');el.volume=.3;$('#play').onclick=async()=>{if(!el.paused){el.pause();return;}try{await el.play();}catch{$('#audio-status').textContent='Audio nicht verfügbar. Bitte Stream-URL bzw. Datei prüfen.';}};el.onplay=()=>{$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Audio pausieren');$('.wave').classList.add('playing');$('#audio-status').textContent=c.streamUrl?'Stream läuft':'Demo-Loop läuft';};el.onpause=()=>{$('#play').textContent='▶';$('#play').setAttribute('aria-label','Demo-Audio abspielen');$('.wave').classList.remove('playing');$('#audio-status').textContent='Pausiert';};el.onerror=()=>{$('#audio-status').textContent='Audio konnte nicht geladen werden.';};$('#volume').oninput=e=>el.volume=Number(e.target.value);}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const form=$('#contact-form');if(form){const wanted=(params.get('auswahl')||'').split(',').map(id=>c.items.find(x=>x.id===id)).filter(Boolean);if(wanted.length){form.elements.subject.value='Angebot anfragen';form.elements.message.value='Ich interessiere mich unverbindlich für:\n'+wanted.map(x=>'• '+x.title+' ('+money(x.price)+' Beispielpreis)').join('\n')+'\n\nMeine Frage: ';}form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);$('#draft').value=c.name+' – LOKALER ANFRAGEENTWURF\nNicht versendet.\n\nName: '+data.get('name')+'\nE-Mail: '+data.get('email')+'\nAnliegen: '+data.get('subject')+'\n\n'+data.get('message');$('#draft-result').hidden=false;$('#form-status').textContent='Entwurf erstellt. Noch nichts versendet.';};$('#draft-download').onclick=()=>{download($('#draft').value,c.id+'-Anfrage.txt');$('#draft-download').focus();};$('#draft-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#draft').value);$('#form-status').textContent='Entwurf kopiert.';}catch{$('#draft').focus();$('#draft').select();$('#form-status').textContent='Bitte den markierten Text kopieren.';}};if($('#draft-email'))$('#draft-email').onclick=()=>location.href='mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent(form.elements.subject.value)+'&body='+encodeURIComponent($('#draft').value);}
})();
